// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza minimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1) Pega os dados que vieram do Merge
const clientes = $json.body.clientes;
const investimentos = $json.investimentos;

const resultados = [];

// 2) Para cada cliente, monta a recomendação
for (const cliente of clientes) {

  // Converte "R$ 12.500,00" para o número 12500
  const saldoNum = Number(
    cliente.saldo.replace("R$", "").replace(/\./g, "").replace(",", ".")
  );

  // Fica só com os investimentos do perfil do cliente
  const doPerfil = investimentos.filter(inv => inv.perfil === cliente.perfil);

  // Escolhe o de maior mínimo que o saldo consegue pagar
  let escolhido = null;
  for (const inv of doPerfil) {
    if (saldoNum >= inv.minimo) {
      if (escolhido === null || inv.minimo > escolhido.minimo) {
        escolhido = inv;
      }
    }
  }

  // Se nenhum serve, o motivo muda e sugerimos o de menor mínimo
  let motivo = "saldo_ok";
  if (escolhido === null) {
    motivo = "saldo_insuficiente";
    escolhido = doPerfil[0];
    for (const inv of doPerfil) {
      if (inv.minimo < escolhido.minimo) escolhido = inv;
    }
  }

  // 3) Monta as mensagens
  const minimoTxt = "R$ " + escolhido.minimo.toLocaleString("pt-BR", { minimumFractionDigits: 2 });
  const cabecalho = "Olá " + cliente.nome + "! Pelo seu perfil (" + cliente.perfil + "), ";
  let mensagens = [];

  if (motivo === "saldo_ok") {
    mensagens = [
      cabecalho + "uma boa opção é " + escolhido.produto + " (mínimo " + minimoTxt + "). Com seu saldo atual (" + cliente.saldo + ") você já consegue investir. Rentabilidade: " + escolhido.rentabilidade + ".",
      "Oi " + cliente.nome + "! Recomendação para " + cliente.perfil + ": " + escolhido.produto + " (mínimo " + minimoTxt + "). Seu saldo (" + cliente.saldo + ") já atende o mínimo. Rentabilidade: " + escolhido.rentabilidade + ".",
      cliente.nome + ", indo direto ao ponto: para o perfil " + cliente.perfil + ", " + escolhido.produto + " (mínimo " + minimoTxt + "). Você tem " + cliente.saldo + ", então dá pra aplicar.",
    ];
  } else {
    mensagens = [
      cabecalho + "a opção mais acessível é " + escolhido.produto + " (mínimo " + minimoTxt + "). Seu saldo (" + cliente.saldo + ") ainda não atinge esse valor.",
      "Oi " + cliente.nome + "! Para " + cliente.perfil + ", a opção com menor mínimo é " + escolhido.produto + " (" + minimoTxt + "). Seu saldo (" + cliente.saldo + ") ainda não alcança.",
      cliente.nome + ", ainda falta saldo: " + escolhido.produto + " exige " + minimoTxt + " e você tem " + cliente.saldo + ".",
    ];
  }

  // 4) Escolhe uma das 3 mensagens aleatoriamente
  const posicao = Math.floor(Math.random() * mensagens.length);

  resultados.push({
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: cliente.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo: motivo,
    mensagens: mensagens,
    mensagem_escolhida: mensagens[posicao],
  });
}

// 5) Devolve para o próximo nó
return [{
  json: {
    total_clientes: clientes.length,
    total_investimentos: investimentos.length,
    resultados: resultados,
  },
}];

// 1) Pega a lista de clientes já com a recomendação
const resultados = $json.resultados;

// 2) Monta o cabeçalho da tabela (formato Markdown)
let tabela = "| Nome | Email | Perfil | Saldo (R$) | Produto recomendado | Mínimo (R$) | Rentabilidade | Situação |\n";
tabela += "|---|---|---|---|---|---|---|---|\n";

// 3) Uma linha da tabela para cada cliente
for (const r of resultados) {
  let situacao = "Saldo suficiente";
  if (r.motivo !== "saldo_ok") {
    situacao = "Saldo insuficiente";
  }

  tabela += "| " + r.nome + " | " + r.email + " | " + r.perfil + " | " + r.saldo_num +
    " | " + r.recomendacao.produto + " | " + r.recomendacao.minimo +
    " | " + r.recomendacao.rentabilidade + " | " + situacao + " |\n";
}

// 4) Devolve a tabela (para a IA) e a lista original (para usar depois)
return [{
  json: {
    total_clientes: resultados.length,
    tabela: tabela,
    clientes: resultados,
  },
}];

// 1) Texto que a IA devolveu e lista original de clientes
let texto = $json.output;
const clientes = $("Preparar dados").first().json.clientes;

// 2) Recorta só o que está entre [ e ] (tira ```json e textos extras)
const inicio = texto.indexOf("[");
const fim = texto.lastIndexOf("]");

let emailsIA = [];
if (inicio !== -1 && fim !== -1) {
  try {
    emailsIA = JSON.parse(texto.slice(inicio, fim + 1));
  } catch (erro) {
    emailsIA = []; // JSON quebrado: vamos usar a mensagem padrão
  }
}
if (!Array.isArray(emailsIA)) {
  emailsIA = [];
}

const saida = [];

// 3) Para cada cliente, procura o e-mail que a IA escreveu para ele
for (const cliente of clientes) {
  let achado = null;
  for (const item of emailsIA) {
    if (item && item.email && item.email.trim().toLowerCase() === cliente.email.toLowerCase()) {
      achado = item;
    }
  }

  // Valores padrão (usados se a IA falhar)
  let assunto = "Sua recomendação de investimento";
  let mensagem = cliente.mensagem_escolhida;
  let origem = "padrao";

  // 4) Regras: aceita o texto da IA só se estiver completo e sem promessa de ganho
  if (achado && achado.assunto && achado.mensagem) {
    const msg = String(achado.mensagem).replace(/\*/g, "").trim(); // tira asteriscos
    const temPromessa = msg.toLowerCase().includes("garantid");

    if (msg !== "" && !temPromessa) {
      assunto = String(achado.assunto).replace(/\*/g, "").trim();
      mensagem = msg;
      origem = "ia";
    }
  }

  // 5) Aviso de risco no final, se a IA não tiver colocado
  if (!mensagem.toLowerCase().includes("risco")) {
    mensagem = mensagem + "\n\nInvestimentos envolvem riscos. Rentabilidade passada não garante resultados futuros.";
  }

  // 6) Gmail em modo HTML ignora "\n", então trocamos por <br> (quebra de linha em HTML)
  const htmlBody = "<p>" + mensagem.replace(/\n\n/g, "</p><p>").replace(/\n/g, "<br>") + "</p>";

  // 7) Guarda o e-mail pronto deste cliente
  saida.push({
    json: {
      nome: cliente.nome,
      email: cliente.email,
      assunto: assunto,
      mensagem: mensagem,
      html_body: htmlBody,
      origem: origem,
    },
  });
}

// 8) Devolve um item por cliente (o Gmail vai rodar uma vez para cada)
return saida;
